const body = $input.first().json.body || {};
const cita = body.cita || {};
const tipo = body.tipoEvento || 'evento';
const [y, m, d] = String(cita.fecha || '').split('-');
const fechaBO = d && m && y ? `${d}/${m}/${y}` : (cita.fecha || '');

const titulos = {
  cita_creada: 'Nueva cita registrada',
  cita_confirmada: 'Tu cita fue confirmada',
  cita_cancelada: 'Aviso de cancelación de cita'
};

const titulo = titulos[tipo] || 'Actualización de cita';
const mensajeCliente = `Hola ${cita.clienteNombre || 'cliente'}, ${titulo.toLowerCase()} en HERMOSA TALITA KUMI (${cita.sucursalNombre}) para ${cita.servicioNombre} el ${fechaBO} a las ${cita.hora}.`;
const mensajeEncargado = `[${titulo}] Sucursal ${cita.sucursalNombre}: ${cita.clienteNombre} (${cita.clienteTelefono || 'sin teléfono'}) — ${cita.servicioNombre}, ${fechaBO} ${cita.hora} (Estado: ${cita.estado}).`;

return [{
  json: {
    tipoEvento: tipo,
    citaId: body.citaId,
    telefonoCliente: cita.clienteTelefono || '',
    whatsappSucursal: cita.sucursalWhatsapp || '',
    mensajeCliente,
    mensajeEncargado
  }
}];
